function resolveEnemySpacing(){ const p=state.player; const pr=state.mount==='horse'&&p.unlocked.has('horse')?28:18, er=16; for(let i=0;i<state.enemies.length;i++){ const e=state.enemies[i]; for(let j=i+1;j<state.enemies.length;j++){ const o=state.enemies[j], dx=o.x-e.x, dy=o.y-e.y, d=Math.hypot(dx,dy)||1, min=er*2; if(d<min){ const push=(min-d)*0.5, nx=dx/d, ny=dy/d; e.x-=nx*push; e.y-=ny*push; o.x+=nx*push; o.y+=ny*push; } } const dx=p.x-e.x, dy=p.y-e.y, d=Math.hypot(dx,dy)||1, min=pr+er; if(d<min){ const nx=dx/d, ny=dy/d, push=min-d; e.x-=nx*push*0.65; e.y-=ny*push*0.65; p.x+=nx*push*0.35; p.y+=ny*push*0.35; p.vx+=nx*18; p.vy+=ny*18; let hit=0.045*(e.power||1)*(e.kind==='turtle'||e.kind==='turkey'?2.2:e.kind==='eagle'?1+Math.min(3,Math.hypot(e.vx||0,e.vy||0)/180):1); if(p.shield&&Math.random()<0.3){hit*=0.7;p.vx+=nx*22;p.vy+=ny*22;e.vx-=nx*22;e.vy-=ny*22;dbg('[SHIELD] blocked 30% contact damage');} p.hp=Math.max(0,p.hp-hit); if(['swamp','axe','marsh'].includes(e.zone))addStatus(p,'poison',0.02*(e.power||1)); } } }
